<?php
$rows=$pdo->query("SELECT v.id,v.code,v.name,v.category,COALESCE(vp.score,0) score,COALESCE(vp.quality_score,0) quality_score,COALESCE(vp.delivery_score,0) delivery_score,COALESCE(vp.compliance_score,0) compliance_score FROM vendors v LEFT JOIN vendor_performance vp ON vp.vendor_id=v.id AND vp.period_label='Current' WHERE v.status='Active' ORDER BY score DESC,v.name")->fetchAll();
?><div class="page-head"><div><h1>Vendor Performance</h1><p>Monitoring kualitas, delivery, dan compliance vendor.</p></div><button class="btn btn-outline-primary"><i class="bi bi-download me-1"></i> Export Report</button></div><div class="row g-4 mb-4"><div class="col-md-4"><div class="summary-tile"><span>Average Score</span><strong><?=number_format(count($rows)?array_sum(array_column($rows,'score'))/count($rows):0,2)?></strong><small>Current period</small></div></div><div class="col-md-4"><div class="summary-tile"><span>Active Vendors</span><strong><?=count($rows)?></strong><small>Vendor master</small></div></div><div class="col-md-4"><div class="summary-tile"><span>Top Score</span><strong><?=number_format($rows?max(array_column($rows,'score')):0,2)?></strong><small>Best current rating</small></div></div></div><div class="card p-3"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Vendor</th><th>Category</th><th>Overall</th><th>Quality</th><th>Delivery</th><th>Compliance</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=de($r['name'])?></strong><small class="d-block text-muted"><?=de($r['code'])?></small></td><td><?=de($r['category']?:'-')?></td><td><strong><?=number_format((float)$r['score'],2)?></strong> <i class="bi bi-star-fill text-warning"></i></td><td><?=number_format((float)$r['quality_score'],2)?></td><td><?=number_format((float)$r['delivery_score'],2)?></td><td><?=number_format((float)$r['compliance_score'],2)?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="text-center text-muted py-5">Belum ada vendor aktif.</td></tr><?php endif;?></tbody></table></div></div>
